from PIL import Image
import numpy as np, math
def fit(n,rng):
    im=np.array(Image.open('observations/%s.png'%n).convert('RGB')).astype(int)
    R,G,B=im[:,:,0],im[:,:,1],im[:,:,2]
    fl=(abs(R-G)<25)&(R>120)&(R<190)&(G>110)&(B>90)&(B<165)&(R-B>15)
    t={}
    for u in range(512):
        c=np.nonzero(fl[:,u])[0]
        if len(c) and c.min()>257: t[u]=int(c.min())
    P=[]
    for u in rng:
        if u in t:
            D=396.8/(t[u]-256.); P.append([D*(u-256)/256., D])
    P=np.array(P)
    if len(P)<6: return None
    c=P.mean(0); A=P-c; _,_,V=np.linalg.svd(A); d=V[0]; nn=np.array([-d[1],d[0]])
    return abs(nn@c), np.abs(A@nn).std(), len(P), math.degrees(math.atan2(d[0],d[1]))
print('obs_0004 h=135 (SE): LEFT=east wall, RIGHT=south wall')
for lab,rng in [('L/east',range(4,240,4)),('R/south',range(280,508,4))]:
    r=fit('obs_0004',rng)
    print('  ',lab, 'perp=%.3f rms=%.4f n=%d ang=%.2f'%r if r else 'no floor')
print('obs_0006 h=225 (SW): LEFT=south wall, RIGHT=west wall')
for lab,rng in [('L/south',range(4,240,4)),('R/west',range(280,508,4))]:
    r=fit('obs_0006',rng)
    print('  ',lab, 'perp=%.3f rms=%.4f n=%d ang=%.2f'%r if r else 'no floor')
